import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/2ms.Lv6_byj-.PNG",s="/assets/4ms.DnwH6j3C.PNG",i="/assets/5ms.DZ0vWdi9.PNG",c="/assets/6ms.DXVSer8x.png",b=JSON.parse('{"title":"Mstock","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/mstock.md","filePath":"connect-brokers/brokers/mstock.md"}'),l={name:"connect-brokers/brokers/mstock.md"};function d(g,e,p,u,h,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mstock" tabindex="-1">Mstock <a class="header-anchor" href="#mstock" aria-label="Permalink to &quot;Mstock&quot;">​</a></h1><p>MStock is a modern Indian stock broker by Mirae Asset, offering commission-free trading and robust REST-based APIs. These APIs enable traders and developers to automate trading, retrieve account information, and integrate market data seamlessly. By connecting mStock OpenAPI with Tradeboard, algo traders can efficiently execute strategies, manage positions, and automate workflows.</p><p>For developers and algo traders looking to use the mStock API, the integration process involves the following steps:</p><h3 id="step-by-step-integration" tabindex="-1"><strong>Step-by-Step Integration</strong> <a class="header-anchor" href="#step-by-step-integration" aria-label="Permalink to &quot;**Step-by-Step Integration**&quot;">​</a></h3><h4 id="step-1-prepare-your-trading-credentials" tabindex="-1"><strong>Step 1: Prepare Your Trading Credentials</strong> <a class="header-anchor" href="#step-1-prepare-your-trading-credentials" aria-label="Permalink to &quot;**Step 1: Prepare Your Trading Credentials**&quot;">​</a></h4><p>Ensure you have your mStock <strong>Client Code</strong> (Login ID) and <strong>Trading Password</strong> ready.</p><p>You will also need access to your registered mobile number/email for OTP verification unless TOTP is enabled.</p><h4 id="step-2-register-for-api-access" tabindex="-1"><strong>Step 2: Register for API Access</strong> <a class="header-anchor" href="#step-2-register-for-api-access" aria-label="Permalink to &quot;**Step 2: Register for API Access**&quot;">​</a></h4><p>mStock provides API access via its OpenAPI portal.</p><ul><li>Visit the API Key genration website:<br><a href="https://www.mstock.com/trading-api" target="_blank" rel="noreferrer"><strong>https://www.mstock.com/trading-api</strong></a></li></ul><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><ul><li>Log in using your trading account credentials.</li><li><strong>Open Menu</strong> - Click on the hamburger menu icon located at the top-left corner of the screen.</li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><ul><li><strong>Navigate to Trading APIs</strong> - In the menu, go to <strong>Products</strong> - Then click on <strong>Trading APIs</strong></li></ul><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><ul><li>Click <strong>Generate New API Key</strong> and give API Type as Type B.</li></ul><figure><img src="'+c+`" alt=""><figcaption></figcaption></figure><ul><li><strong>Enable TOTP</strong> - You will see an option labeled &quot;Generate TOTP&quot; - Click on it to begin the TOTP setup process</li><li>Copy your API Key.</li></ul><h4 id="retrieve-api-credentials" tabindex="-1"><strong>Retrieve API Credentials:</strong> <a class="header-anchor" href="#retrieve-api-credentials" aria-label="Permalink to &quot;**Retrieve API Credentials:**&quot;">​</a></h4><ul><li>Your trading account number or Client Code will be your API Key.</li><li>Copy the API Key generated and use as your API Secret</li></ul><h4 id="configuration" tabindex="-1">Configuration: <a href="#configuration" id="configuration"></a> <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration: &lt;a href=&quot;#configuration&quot; id=&quot;configuration&quot;&gt;&lt;/a&gt;&quot;">​</a></h4><p>Set up your environment variables in a <code>.env</code> file for mstock&#39;s API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_mstock_unique_client_code&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_mstock_api_key_generated&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/mstock/callback&#39;</span></span></code></pre></div><p>Integrating with <strong>mstock APIs</strong> unlocks the ability to automate strategies, execute trades, and analyze data directly within your own infrastructure. When used with <strong>Tradeboard</strong>, you can self-host and run your entire algo trading stack, with full control and zero vendor lock-in.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/mstock/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,27)])])}const k=t(l,[["render",d]]);export{b as __pageData,k as default};
